Spec-first implementation. Here is the contract, save it as spec/openapi.yaml and implement a Flask app to satisfy it exactly:

openapi: 3.0.3
info: {title: Inventory, version: 1.0.0}
paths:
  /items:
    get:
      parameters: [{name: min_qty, in: query, schema: {type: integer, minimum: 0}}]
      responses:
        '200': {description: ok, content: {application/json: {schema: {type: array, items: {$ref: '#/components/schemas/Item'}}}}}
    post:
      requestBody: {required: true, content: {application/json: {schema: {$ref: '#/components/schemas/NewItem'}}}}
      responses:
        '201': {description: created, content: {application/json: {schema: {$ref: '#/components/schemas/Item'}}}}
        '422': {description: invalid}
components:
  schemas:
    NewItem: {type: object, required: [name, qty], properties: {name: {type: string, minLength: 1}, qty: {type: integer, minimum: 0}}, additionalProperties: false}
    Item: {allOf: [{$ref: '#/components/schemas/NewItem'}, {type: object, required: [id], properties: {id: {type: integer}}}]}

Write a verifier test that loads the YAML and asserts every implemented response validates against the corresponding schema (jsonschema), plus behavioral tests for min_qty filtering and additionalProperties rejection. pytest green.

