"""Inventory API implemented to satisfy spec/openapi.yaml exactly."""

from flask import Flask, jsonify, request

app = Flask(__name__)

# In-memory store: list of {"id": int, "name": str, "qty": int}
ITEMS = []
_NEXT_ID = 1


class ValidationError(Exception):
    """Raised when a request body violates the NewItem schema."""


def _validate_new_item(body):
    if not isinstance(body, dict):
        raise ValidationError("body must be a JSON object")
    allowed = {"name", "qty"}
    if set(body) - allowed:
        raise ValidationError("additional properties are not allowed")
    for field in ("name", "qty"):
        if field not in body:
            raise ValidationError(f"missing required field: {field}")
    name = body["name"]
    qty = body["qty"]
    if not isinstance(name, str) or len(name) < 1:
        raise ValidationError("name must be a string with minLength 1")
    # bool is an int subclass in Python; reject it explicitly.
    if not isinstance(qty, int) or isinstance(qty, bool) or qty < 0:
        raise ValidationError("qty must be an integer >= 0")


@app.get("/items")
def list_items():
    min_qty = request.args.get("min_qty")
    if min_qty is not None:
        try:
            min_qty_val = int(min_qty)
        except ValueError:
            return jsonify({"error": "min_qty must be an integer"}), 422
        if min_qty_val < 0:
            return jsonify({"error": "min_qty must be >= 0"}), 422
        items = [it for it in ITEMS if it["qty"] >= min_qty_val]
    else:
        items = ITEMS
    return jsonify(items), 200


@app.post("/items")
def create_item():
    body = request.get_json(silent=True)
    try:
        _validate_new_item(body)
    except ValidationError as exc:
        return jsonify({"error": str(exc)}), 422

    global _NEXT_ID
    item = {
        "id": _NEXT_ID,
        "name": body["name"],
        "qty": body["qty"],
    }
    _NEXT_ID += 1
    ITEMS.append(item)
    return jsonify(item), 201

